###   6.在链表上排序。要求时间复杂度O(n*logn),额外空间复杂度O(1),还要求排序有稳定性，（在数组层面上不能实现）

####           code:

```c
//从当前的p结点往下数k个找到当前组的结束结点并返回 
PNODE getEnd(PNODE pS,int k){
	PNODE p=pS; 
	while(p->pNext!=NULL && --k!=0){//先判断结点的next域是否为NULL，若为NULL则不进循环直接退出NULL前的一个结点便于后续r1或者r2的寻找；反之，若不为NULL则先--k,得到判断k-1后与0的关系，k为1时仍为该指针--k==0，跳出循环成立 
		p=p->pNext;
	}
	return p;
}
PNODE start;//每组排序后的头结点 
PNODE end;//每组排序后的尾结点 
//l1……r1->NULL:有序的左部分
//l2……r2->NULL:有序的右部分 
//整体merge在一起，并且保证有序
//将全局变量start设置为整体的头结点，全局变量end设置为整体的尾结点 
void merge(PNODE l1,PNODE r1,PNODE l2,PNODE r2){
	PNODE pre=NULL;
	//第一次比较同样特别处理，要将start指到整体的最小值节点上去 
	if(l1->data<=l2->data){
		start=l1;
		pre=l1;
		l1=l1->pNext;
	}else{
		start=l2;
		pre=l2;
		l2=l2->pNext;
	}
	while(l1!=NULL && l2!=NULL){
		if(l1->data<=l2->data){
			pre->pNext=l1;
			pre=l1;
			l1=l1->pNext;
		}else{
            pre->pNext=l2;
			pre=l2;
			l2=l2->pNext;		
		} 
	}
	if(l1!=NULL){
		pre->pNext=l1;
		end=r1;
	}//左部分更长，直接将已经排好序的接在末尾即可，并且是以r1作为尾结点end的 
	else{
		pre->pNext=l2;
		end=r2;
	}//右部分更长，直接将已经排好序的接在末尾即可，并且是以r2作为尾结点end的
	return ;
}
//为了使额外空间复杂度为O(1),不能使用递归，因为mergeSort递归需要O(logn)的额外空间 
PNODE perfectSort(PNODE head){
	int len=0;//获得链表长度 
	PNODE cur=head;
	while(cur!=NULL){
		len++;
		cur=cur->pNext;
	}
	//l1……r1 每组的左部分
	//l2……r2 每组的右部分
	//next 下一组的头结点
	//lastGroupEnd 上一组的尾结点
	PNODE l1,r1,l2,r2,next,lastGroupEnd;
	int step=1;
	for(step;step<len;step<<=1){
		//第一组很特殊，因为要决定整个链表的头结点，所以要单独处理
		l1=head;
		r1=getEnd(l1,step);
		l2=r1->pNext;
		r2=getEnd(l2,step);
		next=r2->pNext;
		r1->pNext=NULL;
		r2->pNext=NULL;
		merge(l1,r1,l2,r2);
		head=start;
		lastGroupEnd=end;
		while(next!=NULL){
			l1=next;
			r1=getEnd(l1,step);
			l2=r1->pNext;
			if(l2==NULL){
				lastGroupEnd->pNext=l1;
				break;
			}
			r2=getEnd(l2,step);
			next=r2->pNext;
			r1->pNext=NULL;
			r2->pNext=NULL;
			merge(l1,r1,l2,r2);
			lastGroupEnd->pNext=start;
			lastGroupEnd=end;
		} 
	}
	return head;
}
```

