     ### 4.判断链表是否为回文结构：

           #### 技巧：

快慢指针求中点：慢指针和快指针一开始都指向头结点，慢指针一次跳一个，快指针一次跳两个，当快指针的next域为NULL或快指针为空时停止，此时慢指针指在近似中点的节点位置
          ####  code:

```c
int is_Palidrome(PNODE head){
	//特判head为空和链表只有一个节点的情况，此时一定为回文结构 
	if(head==NULL || head->pNext==NULL){
		return 1;//1代表是回文结构 
	}
	PNODE slow=head;
	PNODE fast=head;
	//利用快慢指针的方法寻找链表的类似中点
	while(fast->pNext!=NULL && fast->pNext->pNext!=NULL){
		slow=slow->pNext;
		fast=fast->pNext->pNext;
	}
	//现在slow为链表的类似中点，从中点开始往后的结点开始逆序
	PNODE pre=slow;
	PNODE cur=pre->pNext;
	PNODE next=NULL;
	pre->pNext=NULL;
	while(cur!=NULL){
		next=cur->pNext;
		cur->pNext=pre;
		pre=cur;
		cur=next;
	} 
	//上述过程已完成了链表左右侧均向中间指
	//head……slow……pre 
	PNODE left=head;
	PNODE right=pre;
	int ans=1;
	while(left!=NULL && right!=NULL){
		if(left->data!=right->data){
			ans=0;//0代表不是回文结构 
            break;		
 		}
		left=left->pNext;
		right=right->pNext;
	}
	//将原链表调整辉原来的样子 
	cur=pre->pNext;
	pre->pNext=NULL;
	next=NULL;
	while(cur!=NULL){
		next=cur->pNext;
		cur->pNext=pre;
		pre=cur;
		cur=next;
	} 
	return ans; 
}
