int fd_lookup(int fdnum, struct Fd **fd) {
        u_int va;
        if (fdnum >= MAXFD) {
                return -E_INVAL;
        }
        va = INDEX2FD(fdnum);
        if ((vpt[va / PTMAP] & PTE_V) != 0) { // the fd is used
                *fd = (struct Fd *)va;
                return 0;
        }
        return -E_INVAL;
