                uint16_t data = ioread16(pa);
                *(uint16_t *)va = data;
        }
        else if (len == 4) {
                //len为4，利用ioread32()读出1字内容写入va实现读出内容的操作
                uint32_t data = ioread32(pa);
                *(uint32_t *)va = data;
        }
        else {
                return -E_INVAL;
        }
        return 0;
