void save_block_link(struct File *f, int nblk, int bno) {
        assert(nblk < NINDIRECT); // if not, file is too large !

        if (nblk < NDIRECT) {
                f->f_direct[nblk] = bno;
        } else {
                if (f->f_indirect == 0) {
                        // create new indirect block.
                        f->f_indirect = next_block(BLOCK_INDEX);
                }
