// Make new block contains link to files in a directory.
int make_link_block(struct File *dirf, int nblk) {
        int bno = next_block(BLOCK_FILE);
        save_block_link(dirf, nblk, bno);
        dirf->f_size += BLOCK_SIZE;
        return bno;
