static int pipe_close(struct Fd *fd) {
        // Unmap 'fd' and the referred Pipe.
        syscall_mem_unmap(0, fd);
        syscall_mem_unmap(0, (void *)fd2data(fd)); //上述两个系统调用替换位置即可
        return 0;
}
