        //为该进程分配一片物理页作为开辟的物理空间
        try(page_alloc(&pp));
        /* Step 4: Map the allocated page at 'va' with permission 'perm' using 'page_insert'. */
        //在相应进程空间中建立虚实地址间的映射关系
        return page_insert(env->env_pgdir, env->env_asid, pp, va, perm);
}

